script:
class CRMDeal {
    onLoad() {
        if (this.doc.__newDocument) return;

        this.actions = this.actions || [];

        this.actions.push({
            label: "Generar ventajas",

            onClick: (close) => {
                if (close) close();

                createDialog({
                    title: "Generar ventajas",

                    message:
                        "Se crearán las tareas correspondientes al Partner Tier " +
                        "asignado a este patrocinio. " +
                        "Si las ventajas ya se generaron anteriormente, " +
                        "se volverán a crear. ¿Quieres continuar?",

                    actions: [
                        {
                            label: "Generar ventajas",
                            variant: "solid",

                            onClick: async ({ close: dialogClose }) => {
                                dialogClose();

                                try {
                                    const result = await call(
                                        "aura.services.partner_tasks.generate_partner_tasks",
                                        {
                                            deal_name: this.doc.name,
                                        }
                                    );

                                    if (result?.success) {
                                        toast.success(result.message);
                                    } else {
                                        toast.error(
                                            result?.message ||
                                            "No se han podido generar las ventajas."
                                        );
                                    }

                                } catch (error) {
                                    console.error(
                                        "Error generando ventajas AURA:",
                                        error
                                    );

                                    toast.error(
                                        "No se han podido generar las ventajas: " +
                                        (
                                            error?.message ||
                                            "se ha producido un error inesperado."
                                        )
                                    );
                                }
                            },
                        },

                        {
                            label: "Cancelar",
                            variant: "outline",

                            onClick: ({ close: dialogClose }) => {
                                dialogClose();
                            },
                        },
                    ],
                });
            },
        });
    }
}
